  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,pct\n29,84.49\n28,85.11\n27,86.7\n26,86.58\n25,87.91\n24,88.13\n23,87.97\n22,88.76\n21,87.97\n20,88.29\n19,87.29\n18,86.7\n17,86.47\n16,86.24\n15,84.31\n14,83.57\n13,83.33\n12,83.05\n11,81.84\n10,81.07\n9,81.61\n8,80.07\n7,81.35\n6,80.75\n5,80.96\n4,81.52\n3,82.53\n2,84.11\n1,84.03\n0,86.9\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time pct",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n23,41\n22,42\n21,45\n20,43\n19,47\n18,48\n17,54\n16,58\n15,55\n14,61\n13,58\n12,63\n11,59\n10,60\n9,60\n8,57\n7,53\n6,54\n5,47\n4,45\n3,44\n2,41\n1,39\n0,54\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"cyc,slot,n\n0,0,48\n0,1,71\n0,2,80\n0,3,70\n0,4,79\n0,5,80\n0,6,47\n1,0,45\n1,1,77\n1,2,72\n1,3,76\n1,4,75\n1,5,73\n1,6,55\n2,0,51\n2,1,72\n2,2,77\n2,3,69\n2,4,69\n2,5,76\n2,6,50\"\n| eval _time=relative_time(now(), \"@w0\") + slot*86400 - cyc*604800\n| where _time<=now() AND _time>now()-1209600\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,d\n11,5.72\n10,5.71\n9,5.75\n8,5.66\n7,5.7\n6,5.56\n5,5.59\n4,5.58\n3,5.56\n2,5.47\n1,5.4\n0,5.3\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time d",
